arguments.command:
python3 -I -c "
import json
for p in ['8081','8082','8083']:
    d=json.load(open(f'/tmp/gpuwork/openapi_{p}.json'))
    print('='*20, p, d.get('info',{}).get('title'))
    for path, ops in d['paths'].items():
        for method, op in ops.items():
            print(f'{method.upper():6} {path:45} {op.get(\"summary\",\"\")}')
"

