arguments.command:
python3 -I -c "
import json
for p in ['8081','8082','8083']:
    d=json.load(open(f'/tmp/gpuwork/openapi_{p}.json'))
    print('='*25, p)
    print(json.dumps(d.get('components',{}), ensure_ascii=False, indent=1))
    for path, ops in d['paths'].items():
        for method, op in ops.items():
            if 'requestBody' in op:
                print(method.upper(), path, '->', json.dumps(op['requestBody'], ensure_ascii=False))
"

raw_arguments.command:
python3 -I -c "
import json
for p in ['8081','8082','8083']:
    d=json.load(open(f'/tmp/gpuwork/openapi_{p}.json'))
    print('='*25, p)
    print(json.dumps(d.get('components',{}), ensure_ascii=False, indent=1))
    for path, ops in d['paths'].items():
        for method, op in ops.items():
            if 'requestBody' in op:
                print(method.upper(), path, '->', json.dumps(op['requestBody'], ensure_ascii=False))
"

