14	</style></head><body>
15	<div class="top">
16	  <div><h2 style="margin:0">Team Demand &amp; Negotiation Desk (:8082)</h2><div style="color:#94a3b8;font-size:13px">协商错峰、压缩卡数与发起 SLA 签收</div></div>
17	  <div style="display:flex;gap:12px"><a href="http://127.0.0.1:8081/" target="_blank" style="color:#93c5fd">Rack Console (:8081)</a><a href="http://127.0.0.1:8083/" target="_blank" style="color:#93c5fd">FinOps (:8083)</a></div>
18	</div>
19	<div id="cards" class="cards"></div>
20	<div class="arch"><h3>历史审批与事故归档</h3><pre id="arch" style="color:#cbd5e1"></pre></div>
21	<script>
22	async function load(){
23	  const r = await fetch('/api/tickets'); const d = await r.json();
24	  document.getElementById('arch').textContent = JSON.stringify(d.archive, null, 2);
25	  const c = document.getElementById('cards'); c.innerHTML = '';
26	  for(const t of d.tickets){
27	    const div = document.createElement('div'); div.className = 'card';
28	    const logs = t.logs.map(l => `[${l.sender}] ${l.message}`).join('
29	');
30	    div.innerHTML = `<div style="display:flex;justify-content:space-between"><strong>${t.team_id} · ${t.team_name}</strong><span class="badge ${t.status}">${t.status}</span></div>
31	    <div style="font-size:12px;color:#94a3b8;margin:6px 0">TDP: ${t.tdp_class} (${t.tdp_kw}kW/bay) | 需求: ${t.req_bays} bays (${t.req_bays*4} GPUs) | 班次: ${t.accepted_shift}</div>
32	    <div style="font-size:13px;margin-bottom:8px">${t.summary}</div>
33	    <div style="font-size:12px;color:#fcd34d;margin-bottom:8px">${t.feedback || ''}</div>
34	    <div style="display:flex;gap:6px;margin-bottom:8px">
35	      <input id="msg-${t.team_id}" placeholder="输入协商方案，如：提供Spine-B RDMA降至16卡">
36	      <button class="btn" onclick="neg('${t.team_id}')">协商</button>
37	      <button class="btn ok" onclick="signoff('${t.team_id}')">签收</button>
38	      <button class="btn gray" onclick="deferT('${t.team_id}')">挂起</button>
39	    </div>
40	    <pre style="background:#0f172a;padding:8px;border-radius:6px;font-size:11px;max-height:90px;overflow:auto;white-space:pre-wrap">${logs}</pre>`;
41	    c.appendChild(div);
42	  }
43	}
44	async function neg(id){
45	  const msg = document.getElementById('msg-'+id).value;
46	  await fetch('/api/tickets/'+id+'/negotiate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:msg})});
47	  load();
48	}
49	async function signoff(id){
50	  const r = await fetch('/api/tickets/'+id+'/signoff',{method:'POST'});
51	  const d = await r.json(); if(!d.ok) alert(d.feedback); load();
52	}
53	async function deferT(id){
54	  const r = await fetch('/api/tickets/'+id+'/defer',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:'Deferred via Desk UI'})});
55	  const d = await r.json(); if(!r.ok) alert(d.detail); load();
56	}
57	load();
58	</script></body></html>

