#!/usr/bin/env python3
"""Helper for the three internal cluster systems (cookie auth via curl jars)."""
import json, subprocess, sys

PORTS = {"rack": 8081, "desk": 8082, "fin": 8083}

def call(svc, method, path, body=None):
    port = PORTS[svc]
    cmd = ["curl", "-s", "-m", "30", "-b", f"/tmp/gpuwork/cookies_{port}.txt",
           "-X", method, f"http://127.0.0.1:{port}{path}",
           "-w", "\n%{http_code}"]
    if body is not None:
        cmd += ["-H", "Content-Type: application/json", "-d", json.dumps(body)]
    out = subprocess.run(cmd, capture_output=True, text=True).stdout
    payload, _, code = out.rpartition("\n")
    try:
        return int(code), json.loads(payload)
    except Exception:
        return int(code), payload

if __name__ == "__main__":
    svc, method, path = sys.argv[1], sys.argv[2], sys.argv[3]
    body = json.loads(sys.argv[4]) if len(sys.argv) > 4 else None
    code, resp = call(svc, method, path, body)
    print(code)
    print(json.dumps(resp, ensure_ascii=False, indent=1))

